267:   const h3 = hash2(bx * 131 + by * 97 + cx * 23 + cy * 29);
268:   const w = 7 + (h2 >>> 0) % 10;
269:   const d = 7 + (h3 >>> 0) % 10;
270:   const stories = 3 + ((hash2(bx * 53 + by * 61 + cx * 5 + cy * 7) >>> 0) % 7);
271:   const bh = stories * 3.1;
272:   const lotOx = bx * CELL + ROAD / 2 + 1.5;
273:   const lotOz = by * CELL + ROAD / 2 + 1.5;
